// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address sender = address(0x1234);
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 1}('');
        require(ok, "fallback call failed");

        assertEq(c.depositsCount(), 1);
    }
}
